package com.buildingtracker.firestore;import android.app.*;import android.os.*;import android.webkit.*;public class MainActivity extends Activity{WebView w;MongoStore m;public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);m=new MongoStore();w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.addJavascriptInterface(new Bridge(),"FirestoreBridge");setContentView(w);w.loadUrl("file:///android_asset/index.html");}class Bridge{String q(String x){return "'"+x.replace("\\","\\\\").replace("'","\\'").replace("\n","\\n")+"'";}MongoStore.Call c(String ok){return new MongoStore.Call(){public void ok(String j){w.post(()->w.evaluateJavascript(ok+"("+q(j)+")",null));}public void bad(String e){w.post(()->w.evaluateJavascript("failed("+q(e)+")",null));}};}@JavascriptInterface public void loadAll(){m.all(c("loaded"));}@JavascriptInterface public void put(String t,String j){m.put(t,j,c("saved"));}@JavascriptInterface public void deleteRecord(String t,String id,String r){m.delete(t,id,Integer.parseInt(r),c("deleted"));}}}